{
  "findings": [
    {
      "ref": "[D503]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child, and this feature is on by default.",
      "stance": "risk",
      "quote": "Roblox offers various ways for Users to communicate across the Platform and the Roblox Creator Platform (collectively, “Communication Features”). You must complete an age check before using Communication Features."
    },
    {
      "ref": "[D503]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases of Robux that can be used to buy items, and purchases are non-refundable.",
      "stance": "risk",
      "quote": "Roblox offers Robux, available for purchase, for use on the Services. When you acquire or purchase Robux, you receive a limited, non-transferable, revocable license to use Robux to access or use Content made available by Roblox on the Services and in compliance with the Roblox Terms. Robux may not be purchased, used, sold, distributed, or otherwise used, except through channels and mechanisms made available or otherwise approved by Roblox. ... All purchases of Robux or Paid Services are final, non-refundable and non-transferable."
    },
    {
      "ref": "[D503]",
      "area": "data",
      "claim": "A parent reports that the app collects communication content and may share it with third parties, and the data can be deleted.",
      "stance": "neutral",
      "quote": "Roblox may access and review Content, including Content shared via Communication Features and other non-public Content."
    },
    {
      "ref": "[D503]",
      "area": "age_gating",
      "claim": "A parent reports that an age check is required before using communication features.",
      "stance": "mitigation",
      "quote": "You must complete an age check before using Communication Features."
    },
    {
      "ref": "[D503]",
      "area": "content",
      "claim": "A parent reports that the platform may contain user-generated content that is moderated, but moderation is not guaranteed.",
      "stance": "risk",
      "quote": "Roblox has the right, but not the obligation, to monitor, review, modify, disable access to, or remove any UGC or other Content on the Services, in whole or in part, at any time, with or without notice, and without liability to you or any third party."
    },
    {
      "ref": "[D503]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny for its payment and data practices.",
      "stance": "risk",
      "quote": "Roblox may modify, suspend or discontinue the Services, or parts of the Services, including features that involve Robux."
    }
  ]
}
